export interface GlyphCell {
	column: number;
	row: number;
	filled: boolean;
}

/** Reads a glyph drawn in text, one string per row: `#` a solid dot, `o` a ring, anything else empty. */
export function glyphCellsFromRows(rows: string[]): GlyphCell[] {
	return rows.flatMap((line, row) => [...line].flatMap((mark, column) => (mark === '#' || mark === 'o' ? [{ column, row, filled: mark === '#' }] : [])));
}

import type { GlyphCell } from '@/components/ds/ui/dot-glyph-cells';
import { DOT_ABSENT, DOT_FILLED, DOT_HOLLOW, type DotGrid } from '@/components/ds/ui/dot-morph-dots';
import { clearGooField, createGooField, fuseGooField, readGooField } from '@/components/ds/ui/dot-morph-goo';
import type { DotMorphFrame } from '@/components/ds/ui/dot-morph-player';

/**
 * Melts a glyph made of dots into a drawn shape. The glyph and the shape share one small raster that is blurred and
 * re-cut, so one flows into the other rather than cross-fading.
 */

export interface GlyphMorph {
	grid: DotGrid;
	/** The glyph's square box within the grid, in cells. */
	box: { left: number; top: number; cellsPerSide: number };
	cells: GlyphCell[];
	/**
	 * Draws the shape the glyph becomes, in grid units from the box's top-left corner. Black draws filled dots, white
	 * draws hollow ones. It is asked for every frame, so it can keep moving once the morph has arrived.
	 */
	drawTarget: (context: CanvasRenderingContext2D, frame: DotMorphFrame) => void;
}

// The melt spills a little past the glyph's own box on its way to the new shape.
const MARGIN_CELLS = 4;
const SAMPLES_PER_CELL = 2;
const PRESENT_AT = 0.5;
const FILLED_AT = 0.5;
const GOO_SIGMA_IN_CELLS = 1.4;
const RETREAT_SCALE = 0.78;

const clamp01 = (value: number) => Math.min(1, Math.max(0, value));
const phase = (morph: number, start: number, end: number) => clamp01((morph - start) / (end - start));
const easeInOut = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2);

/** How far the new shape has taken over from the glyph; a target can use it to time its own entrance. */
export const glyphHandover = (morph: number) => easeInOut(phase(morph, 0.3, 0.75));

export function drawGlyphCells(context: CanvasRenderingContext2D, cells: GlyphCell[], pitch: number) {
	for (const cell of cells) {
		// ds-override: offscreen luminance mask sampled into dot states, never painted
		context.fillStyle = cell.filled ? '#000' : '#fff';
		context.fillRect(cell.column * pitch, cell.row * pitch, pitch, pitch);
	}
}

export function glyphRestingDots({ grid, box, cells }: GlyphMorph) {
	const states = new Uint8Array(grid.columns * grid.rows);
	for (const cell of cells) states[(cell.row + box.top) * grid.columns + cell.column + box.left] = cell.filled ? DOT_FILLED : DOT_HOLLOW;
	return states;
}

export function createGlyphShader({ grid, box, cells, drawTarget }: GlyphMorph) {
	const { pitch } = grid;
	const fieldCells = box.cellsPerSide + MARGIN_CELLS * 2;
	const fieldSize = fieldCells * SAMPLES_PER_CELL;
	const fieldScale = SAMPLES_PER_CELL / pitch;
	const boxCenter = (box.cellsPerSide * pitch) / 2;
	const field = createGooField(fieldSize, fieldSize);
	const scratch = new Float32Array(fieldSize * fieldSize);
	const states = new Uint8Array(grid.columns * grid.rows);
	const samples = SAMPLES_PER_CELL * SAMPLES_PER_CELL;

	const drawGlyph = (morph: number) => {
		const scale = 1 + (RETREAT_SCALE - 1) * easeInOut(phase(morph, 0.05, 0.6));
		field.context.save();
		field.context.globalAlpha = 1 - glyphHandover(morph);
		field.context.translate(boxCenter, boxCenter);
		field.context.scale(scale, scale);
		field.context.translate(-boxCenter, -boxCenter);
		drawGlyphCells(field.context, cells, pitch);
		field.context.restore();
	};

	return (frame: DotMorphFrame) => {
		clearGooField(field, fieldScale);
		field.context.translate(MARGIN_CELLS * pitch, MARGIN_CELLS * pitch);
		drawGlyph(frame.morph);
		field.context.save();
		field.context.globalAlpha = glyphHandover(frame.morph);
		drawTarget(field.context, frame);
		field.context.restore();
		readGooField(field);
		const sigma = GOO_SIGMA_IN_CELLS * SAMPLES_PER_CELL * Math.sin(Math.PI * phase(frame.morph, 0.05, 0.95));
		if (sigma > 0.002) fuseGooField(field, scratch, sigma);

		states.fill(DOT_ABSENT);
		for (let fieldRow = 0; fieldRow < fieldCells; fieldRow++) {
			const row = fieldRow - MARGIN_CELLS + box.top;
			if (row < 0 || row >= grid.rows) continue;
			for (let fieldColumn = 0; fieldColumn < fieldCells; fieldColumn++) {
				const column = fieldColumn - MARGIN_CELLS + box.left;
				if (column < 0 || column >= grid.columns) continue;
				let coverage = 0;
				let darkness = 0;
				for (let sampleY = 0; sampleY < SAMPLES_PER_CELL; sampleY++) {
					const rowStart = (fieldRow * SAMPLES_PER_CELL + sampleY) * fieldSize + fieldColumn * SAMPLES_PER_CELL;
					for (let sampleX = 0; sampleX < SAMPLES_PER_CELL; sampleX++) {
						coverage += field.coverage[rowStart + sampleX];
						darkness += field.darkness[rowStart + sampleX];
					}
				}
				if (coverage / samples < PRESENT_AT) continue;
				states[row * grid.columns + column] = darkness / coverage >= FILLED_AT ? DOT_FILLED : DOT_HOLLOW;
			}
		}
		return states;
	};
}

import { paintColor } from '@/components/ds/ui/ds-color';
export interface DotGrid {
	columns: number;
	rows: number;
	pitch: number;
	dotRadius: number;
	ringStroke: number;
	/** How far around each dot the card's colour is repainted, clearing any backdrop pattern the art moves across. */
	haloRadius: number;
	/** How long a dot takes to ease most of the way to its new state; slower reads as a melt rather than a switch. */
	easeSeconds?: number;
}

export interface DotPalette {
	dots: string;
	background: string;
}

export const DOT_ABSENT = 0;
export const DOT_HOLLOW = 1;
export const DOT_FILLED = 2;

const DOT_EASE_SECONDS = 0.04;
const SETTLED_DISTANCE = 0.02;
const VISIBLE_SCALE = 0.04;

export interface DotField {
	seed: (states: Uint8Array) => void;
	/** Eases every dot toward its target state; returns whether they have all arrived. */
	advance: (targets: Uint8Array, seconds: number) => boolean;
	/** Draws in grid units, so the caller's transform decides where the grid lands. */
	draw: (context: CanvasRenderingContext2D, palette: DotPalette) => void;
}

// Each dot carries a size and a fill that ease toward their target, so a moving edge swells and drains its dots
// rather than switching them.
export function createDotField({ columns, rows, pitch, dotRadius, ringStroke, haloRadius, easeSeconds = DOT_EASE_SECONDS }: DotGrid): DotField {
	const cellCount = columns * rows;
	const scale = new Float32Array(cellCount);
	const fill = new Float32Array(cellCount);
	const centerX = (cell: number) => ((cell % columns) + 0.5) * pitch;
	const centerY = (cell: number) => (Math.floor(cell / columns) + 0.5) * pitch;

	return {
		seed(states) {
			for (let cell = 0; cell < cellCount; cell++) {
				scale[cell] = states[cell] === DOT_ABSENT ? 0 : 1;
				fill[cell] = states[cell] === DOT_FILLED ? 1 : 0;
			}
		},
		advance(targets, seconds) {
			const step = 1 - Math.exp(-seconds / easeSeconds);
			let isSettled = true;
			for (let cell = 0; cell < cellCount; cell++) {
				const targetScale = targets[cell] === DOT_ABSENT ? 0 : 1;
				// An absent dot keeps its fill while it shrinks away, so it never flashes hollow on the way out.
				const targetFill = targets[cell] === DOT_ABSENT ? fill[cell] : targets[cell] === DOT_FILLED ? 1 : 0;
				scale[cell] += (targetScale - scale[cell]) * step;
				fill[cell] += (targetFill - fill[cell]) * step;
				if (Math.abs(targetScale - scale[cell]) > SETTLED_DISTANCE || Math.abs(targetFill - fill[cell]) > SETTLED_DISTANCE) isSettled = false;
			}
			return isSettled;
		},
		draw(context, palette) {
			context.fillStyle = paintColor(context, palette.background);
			context.beginPath();
			for (let cell = 0; cell < cellCount; cell++) {
				if (scale[cell] < VISIBLE_SCALE) continue;
				const x = centerX(cell);
				const y = centerY(cell);
				const radius = haloRadius * Math.min(1, scale[cell] * 1.5);
				context.moveTo(x + radius, y);
				context.arc(x, y, radius, 0, Math.PI * 2);
			}
			context.fill();

			context.fillStyle = paintColor(context, palette.dots);
			context.beginPath();
			for (let cell = 0; cell < cellCount; cell++) {
				if (scale[cell] < VISIBLE_SCALE) continue;
				const x = centerX(cell);
				const y = centerY(cell);
				const radius = dotRadius * scale[cell];
				const hole = (dotRadius - ringStroke) * (1 - fill[cell]) * scale[cell];
				context.moveTo(x + radius, y);
				context.arc(x, y, radius, 0, Math.PI * 2);
				if (hole > 0.1) {
					context.moveTo(x + hole, y);
					context.arc(x, y, hole, 0, Math.PI * 2);
				}
			}
			context.fill('evenodd');
		},
	};
}

/**
 * A small raster of a scene, read back as how much of each pixel is covered and how dark that cover is.
 * Blurring it and cutting the blur back to a hard edge is what grows liquid necks between shapes that come close.
 */
export interface GooField {
	width: number;
	height: number;
	context: CanvasRenderingContext2D;
	coverage: Float32Array;
	darkness: Float32Array;
}

const THRESHOLD_LOW = 0.35;
const THRESHOLD_HIGH = 0.65;
// Below this much blur the threshold is blended in gradually, so a scene can raise its goo from zero without a jump.
const FULL_THRESHOLD_SIGMA = 0.8;

const LINEAR_CHANNEL = Float32Array.from({ length: 256 }, (_, channel) => {
	const c = channel / 255;
	return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
});

export function createGooField(width: number, height: number): GooField {
	const canvas = document.createElement('canvas');
	canvas.width = width;
	canvas.height = height;
	const context = canvas.getContext('2d', { willReadFrequently: true });
	if (!context) throw new Error('2D canvas is unavailable');
	return { width, height, context, coverage: new Float32Array(width * height), darkness: new Float32Array(width * height) };
}

/** Wipes the field and leaves its context scaled, so the scene draws in its own units. */
export function clearGooField({ context, width, height }: GooField, scale: number) {
	context.setTransform(1, 0, 0, 1, 0, 0);
	context.globalAlpha = 1;
	context.globalCompositeOperation = 'source-over';
	context.clearRect(0, 0, width, height);
	context.setTransform(scale, 0, 0, scale, 0, 0);
}

export function readGooField({ context, width, height, coverage, darkness }: GooField) {
	const { data } = context.getImageData(0, 0, width, height);
	// Scenes paint in a handful of flat colours, so neighbouring pixels usually repeat one; reusing its tone skips the cube root.
	let lastRed = -1;
	let lastGreen = -1;
	let lastBlue = -1;
	let lastTone = 0;
	for (let pixel = 0, offset = 0; pixel < coverage.length; pixel++, offset += 4) {
		const alpha = data[offset + 3] / 255;
		if (alpha === 0) {
			coverage[pixel] = 0;
			darkness[pixel] = 0;
			continue;
		}
		const red = data[offset];
		const green = data[offset + 1];
		const blue = data[offset + 2];
		if (red !== lastRed || green !== lastGreen || blue !== lastBlue) {
			lastRed = red;
			lastGreen = green;
			lastBlue = blue;
			lastTone = 1 - Math.cbrt(0.2126 * LINEAR_CHANNEL[red] + 0.7152 * LINEAR_CHANNEL[green] + 0.0722 * LINEAR_CHANNEL[blue]);
		}
		coverage[pixel] = alpha;
		darkness[pixel] = alpha * lastTone;
	}
}

function gaussianKernel(sigma: number) {
	const radius = Math.max(1, Math.ceil(sigma * 3));
	const kernel = new Float32Array(radius * 2 + 1);
	let total = 0;
	for (let offset = -radius; offset <= radius; offset++) {
		const weight = Math.exp(-(offset * offset) / (2 * sigma * sigma));
		kernel[offset + radius] = weight;
		total += weight;
	}
	for (let index = 0; index < kernel.length; index++) kernel[index] /= total;
	return kernel;
}

// Scenes fill only part of the field, so the blur skips everything its kernel can't reach from any content: whole
// rows, and the stretch of each row beyond its content's reach. Those pixels are written as zero, which is exactly what
// summing zeros gives, so the result is unchanged. The vertical pass sums whole rows at a time, walking memory in order
// instead of striding down each column; each pixel's sum still runs in the same order and precision.
interface BlurBuffers {
	sums: Float64Array;
	// Per row, the first and one-past-last column its blurred values can be non-zero in; an empty row has start === end.
	reachStart: Int32Array;
	reachEnd: Int32Array;
}

const blurBuffers = new Map<string, BlurBuffers>();

function blur(values: Float32Array, scratch: Float32Array, width: number, height: number, kernel: Float32Array) {
	const radius = (kernel.length - 1) / 2;
	const key = `${width}x${height}`;
	let buffers = blurBuffers.get(key);
	if (!buffers) {
		buffers = { sums: new Float64Array(width), reachStart: new Int32Array(height), reachEnd: new Int32Array(height) };
		blurBuffers.set(key, buffers);
	}
	const { sums, reachStart, reachEnd } = buffers;

	for (let y = 0; y < height; y++) {
		const rowStart = y * width;
		let first = -1;
		let last = -1;
		for (let x = 0; x < width; x++) {
			if (values[rowStart + x] !== 0) {
				if (first === -1) first = x;
				last = x;
			}
		}
		if (first === -1) {
			reachStart[y] = 0;
			reachEnd[y] = 0;
			scratch.fill(0, rowStart, rowStart + width);
			continue;
		}
		const start = Math.max(0, first - radius);
		const end = Math.min(width, last + radius + 1);
		reachStart[y] = start;
		reachEnd[y] = end;
		scratch.fill(0, rowStart, rowStart + start);
		scratch.fill(0, rowStart + end, rowStart + width);
		for (let x = start; x < end; x++) {
			let sum = 0;
			const from = Math.max(-radius, -x);
			const to = Math.min(radius, width - 1 - x);
			for (let offset = from; offset <= to; offset++) sum += values[rowStart + x + offset] * kernel[offset + radius];
			scratch[rowStart + x] = sum;
		}
	}

	for (let y = 0; y < height; y++) {
		const from = Math.max(-radius, -y);
		const to = Math.min(radius, height - 1 - y);
		const rowStart = y * width;
		let start = width;
		let end = 0;
		for (let offset = from; offset <= to; offset++) {
			const source = y + offset;
			if (reachStart[source] === reachEnd[source]) continue;
			if (reachStart[source] < start) start = reachStart[source];
			if (reachEnd[source] > end) end = reachEnd[source];
		}
		if (start >= end) {
			values.fill(0, rowStart, rowStart + width);
			continue;
		}
		sums.fill(0, start, end);
		for (let offset = from; offset <= to; offset++) {
			const weight = kernel[offset + radius];
			const sourceStart = (y + offset) * width;
			for (let x = start; x < end; x++) sums[x] += scratch[sourceStart + x] * weight;
		}
		values.fill(0, rowStart, rowStart + start);
		for (let x = start; x < end; x++) values[rowStart + x] = sums[x];
		values.fill(0, rowStart + end, rowStart + width);
	}
}

/** `sigma` is in field pixels. */
export function fuseGooField({ width, height, coverage, darkness }: GooField, scratch: Float32Array, sigma: number) {
	const kernel = gaussianKernel(sigma);
	blur(coverage, scratch, width, height, kernel);
	blur(darkness, scratch, width, height, kernel);
	const thresholdBlend = Math.min(1, sigma / FULL_THRESHOLD_SIGMA);
	for (let pixel = 0; pixel < coverage.length; pixel++) {
		const blurred = coverage[pixel];
		if (blurred <= 0.001) {
			coverage[pixel] = 0;
			darkness[pixel] = 0;
			continue;
		}
		const edge = Math.min(1, Math.max(0, (blurred - THRESHOLD_LOW) / (THRESHOLD_HIGH - THRESHOLD_LOW)));
		const cut = edge * edge * (3 - 2 * edge);
		const fused = blurred + (cut - blurred) * thresholdBlend;
		darkness[pixel] *= fused / blurred;
		coverage[pixel] = fused;
	}
}

import { paintColor } from '@/components/ds/ui/ds-color';
import { createDotField, type DotGrid, type DotPalette } from '@/components/ds/ui/dot-morph-dots';

const DEFAULT_MORPH_IN_SECONDS = 1.1;
const MORPH_OUT_SECONDS = 0.7;
const SPIN_UP_SECONDS = 0.45;
const REWIND_STIFFNESS = 70;
const REWIND_DAMPING = 2 * Math.sqrt(REWIND_STIFFNESS);
const REWIND_LOOKAHEAD_SECONDS = 0.2;
const RESTING_SPIN_DISTANCE = 0.004;
const RESTING_SPIN_VELOCITY = 0.02;
// A background tab hands back one huge frame gap; stepping the physics across it would fling the loop.
const LONGEST_FRAME_SECONDS = 0.05;
const MAX_PIXEL_RATIO = 2;

export interface DotMorphFrame {
	/** 0 at rest, 1 once the art has fully become its second picture. */
	morph: number;
	/** Radians travelled by whatever keeps moving while the card stays hovered. */
	spin: number;
}

export interface DotMorphSource {
	grid: DotGrid;
	/** `contain` and `cover` place the grid in the canvas the way the static art is placed in its box. */
	fit: 'contain' | 'cover';
	/** The static art's own dots: the morph starts from them and finishes on them, so swapping the two is invisible. */
	restingDots: Uint8Array;
	spinSpeed: number;
	/** The loop repeats every this many radians, so letting go never rewinds further than half of it. */
	spinPeriod: number;
	sample: (frame: DotMorphFrame) => Uint8Array;
	/**
	 * Backdrop rings the static art leaves out to keep clear of itself. They fade in with the morph, and the dots'
	 * halo clears them again wherever the art now is, so the backdrop follows the new shape instead of the old one.
	 */
	backdrop?: { cells: number[]; opacity: number };
	/** A morph with little choreography to show can arrive sooner than the default. */
	morphInSeconds?: number;
}

export interface DotMorphPlayer {
	setHovering: (isHovering: boolean) => void;
	resize: () => void;
	destroy: () => void;
}

interface DotMorphPlayerOptions {
	canvas: HTMLCanvasElement;
	palette: DotPalette;
	source: DotMorphSource;
	onPlayingChange: (isPlaying: boolean) => void;
}

export function nearestRestingSpin(spin: number, period: number) {
	return Math.round(spin / period) * period;
}

export function createDotMorphPlayer({ canvas, palette, source, onPlayingChange }: DotMorphPlayerOptions): DotMorphPlayer {
	const context = canvas.getContext('2d');
	if (!context) throw new Error('2D canvas is unavailable');
	const { grid, restingDots } = source;
	const gridWidth = grid.columns * grid.pitch;
	const gridHeight = grid.rows * grid.pitch;
	const dots = createDotField(grid);

	let isHovering = false;
	let isPlaying = false;
	let morph = 0;
	let spin = 0;
	let spinVelocity = 0;
	let restingSpin = 0;
	let frameRequest = 0;
	let lastFrameAt = 0;

	const drawBackdrop = ({ cells, opacity }: NonNullable<DotMorphSource['backdrop']>) => {
		context.globalAlpha = opacity * morph;
		context.strokeStyle = paintColor(context, palette.dots);
		context.lineWidth = grid.ringStroke;
		context.beginPath();
		const radius = grid.dotRadius - grid.ringStroke / 2;
		for (const cell of cells) {
			const x = ((cell % grid.columns) + 0.5) * grid.pitch;
			const y = (Math.floor(cell / grid.columns) + 0.5) * grid.pitch;
			context.moveTo(x + radius, y);
			context.arc(x, y, radius, 0, Math.PI * 2);
		}
		context.stroke();
		context.globalAlpha = 1;
	};

	const draw = () => {
		context.setTransform(1, 0, 0, 1, 0, 0);
		context.clearRect(0, 0, canvas.width, canvas.height);
		const fitWidth = canvas.width / gridWidth;
		const fitHeight = canvas.height / gridHeight;
		const scale = source.fit === 'contain' ? Math.min(fitWidth, fitHeight) : Math.max(fitWidth, fitHeight);
		context.setTransform(scale, 0, 0, scale, (canvas.width - gridWidth * scale) / 2, (canvas.height - gridHeight * scale) / 2);
		if (source.backdrop && morph > 0) drawBackdrop(source.backdrop);
		dots.draw(context, palette);
	};

	const resize = () => {
		const pixelRatio = Math.min(window.devicePixelRatio || 1, MAX_PIXEL_RATIO);
		const width = Math.round(canvas.clientWidth * pixelRatio);
		const height = Math.round(canvas.clientHeight * pixelRatio);
		if (canvas.width === width && canvas.height === height) return;
		canvas.width = width;
		canvas.height = height;
		if (isPlaying) draw();
	};

	const step = (now: number) => {
		const seconds = Math.min((now - lastFrameAt) / 1000, LONGEST_FRAME_SECONDS);
		lastFrameAt = now;

		if (isHovering) {
			morph = Math.min(1, morph + seconds / (source.morphInSeconds ?? DEFAULT_MORPH_IN_SECONDS));
			spinVelocity += (source.spinSpeed - spinVelocity) * (1 - Math.exp(-seconds / SPIN_UP_SECONDS));
		} else {
			morph = Math.max(0, morph - seconds / MORPH_OUT_SECONDS);
			spinVelocity += (-REWIND_STIFFNESS * (spin - restingSpin) - REWIND_DAMPING * spinVelocity) * seconds;
		}
		spin += spinVelocity * seconds;

		const isHome = !isHovering && morph === 0 && Math.abs(spin - restingSpin) < RESTING_SPIN_DISTANCE && Math.abs(spinVelocity) < RESTING_SPIN_VELOCITY;
		const isSettled = dots.advance(isHome ? restingDots : source.sample({ morph, spin }), seconds);
		draw();

		if (isHome && isSettled) {
			isPlaying = false;
			spin = 0;
			spinVelocity = 0;
			onPlayingChange(false);
			return;
		}
		frameRequest = requestAnimationFrame(step);
	};

	return {
		setHovering(next) {
			if (next === isHovering) return;
			isHovering = next;
			if (!next) {
				restingSpin = nearestRestingSpin(spin + spinVelocity * REWIND_LOOKAHEAD_SECONDS, source.spinPeriod);
				return;
			}
			if (isPlaying) return;
			isPlaying = true;
			resize();
			dots.seed(restingDots);
			draw();
			onPlayingChange(true);
			lastFrameAt = performance.now();
			frameRequest = requestAnimationFrame(step);
		},
		resize,
		destroy() {
			cancelAnimationFrame(frameRequest);
			isPlaying = false;
		},
	};
}

import { paintColor } from '@/components/ds/ui/ds-color';
import type { GlyphCell } from '@/components/ds/ui/dot-glyph-cells';
import { createGlyphShader, drawGlyphCells } from '@/components/ds/ui/dot-glyph-morph';
import { DOT_ABSENT, DOT_FILLED, type DotGrid } from '@/components/ds/ui/dot-morph-dots';
import { cellsOfStates, clamp01, hasRippleReached, paintedStates, type DotPainter, type GridPoint } from '@/components/ds/ui/dot-story-cells';
import { createDotStoryPlayer, dotStoryFont, paintDotStoryCursor, paintDotStoryText, type DotStoryPlayer, type DotStoryStage, type DotStoryText } from '@/components/ds/ui/dot-story-player';

/**
 * A story told as a loop of beats. Each beat is a picture, how it arrives from the one before, and what moves or is
 * written while it holds. A dense picture melts into the next; one that is mostly outline has too little in it to
 * melt, so it is built up dot by dot or swept in by a wave instead.
 */

export interface StoryPicture {
	states: Uint8Array;
	cells: GlyphCell[];
}

type Arrival =
	| { kind: 'melts'; seconds: number }
	/** Each dot changes once the arrival has reached its share, from 0 (first) to 1 (last). */
	| { kind: 'builds'; seconds: number; order: (column: number, row: number) => number }
	/** The change spreads out from `origin`, lighting each dot as it passes. */
	| { kind: 'waves'; seconds: number; origin: GridPoint };

export interface StoryBeat {
	picture: StoryPicture;
	arrival: Arrival;
	holdSeconds: number;
	/** Moves the held picture's parts: `states` starts as the picture and is changed in place. */
	animate?: (states: Uint8Array, heldSeconds: number) => void;
	/** What `animate` has made of the picture by the end of the hold, when that differs: the next beat arrives from it. */
	departure?: StoryPicture;
	/** Writes over the held picture; `presence` fades the writing in as the beat holds and out as the next arrives. */
	write?: (pen: StoryPen, heldSeconds: number) => void;
	/**
	 * Fills, in the card's colour, the part of the picture left empty for writing, so a backdrop pattern does not show
	 * through it. It stays filled while the next beat arrives, until that beat's own dots have covered it.
	 */
	clears?: (context: CanvasRenderingContext2D) => void;
}

export interface StoryPen {
	text: (text: DotStoryText, presence?: number) => void;
	/** Types `text` from `startsAt` seconds into the hold, with a cursor until `cursorUntil` (the end of typing if unset). */
	type: (text: DotStoryText, heldSeconds: number, typing: { startsAt: number; charactersPerSecond: number; cursorLingers?: number }) => void;
}

const WAVE_CREST_IN_CELLS = 2.5;
const TEXT_FADE_SECONDS = 0.3;
const CURSOR_GAP = 3;

export const pictureOf = (grid: DotGrid, painter: DotPainter): StoryPicture => {
	const states = paintedStates(grid, painter);
	return { states, cells: cellsOfStates(grid, states) };
};

/** How long `text` takes to type, so whatever follows can wait for it. */
export const typingSeconds = (text: DotStoryText, charactersPerSecond: number) => text.text.length / charactersPerSecond;

interface BeatStoryOptions {
	grid: DotGrid;
	beats: StoryBeat[];
	/** The beat the static art shows, and how far into its hold. */
	resting: { beat: number; heldSeconds: number };
}

export function createBeatStoryPlayer({ canvas, dotColor, surfaceColor, fontFamily, onFirstFrame }: DotStoryStage, { grid, beats, resting }: BeatStoryOptions): DotStoryPlayer {
	const { columns, rows, pitch } = grid;
	const states = new Uint8Array(columns * rows);
	const previous = (beat: number) => beats[(beat + beats.length - 1) % beats.length];
	const leftBy = (beat: number) => previous(beat).departure ?? previous(beat).picture;
	const startsAt = beats.map((_, index) => beats.slice(0, index).reduce((total, beat) => total + beat.arrival.seconds + beat.holdSeconds, 0));
	const loopSeconds = startsAt[beats.length - 1] + beats[beats.length - 1].arrival.seconds + beats[beats.length - 1].holdSeconds;
	const farthestCorner = Math.hypot(columns, rows);

	const melts = beats.map((beat, index) => (beat.arrival.kind === 'melts' ? createGlyphShader({ grid, box: { left: 0, top: 0, cellsPerSide: Math.max(columns, rows) }, cells: leftBy(index).cells, drawTarget: (target) => drawGlyphCells(target, beat.picture.cells, pitch) }) : null));

	const arriving = (index: number, arrived: number) => {
		const { picture, arrival } = beats[index];
		const before = leftBy(index).states;
		if (arrival.kind === 'melts') return melts[index]!({ morph: arrived, spin: 0 });
		for (let cell = 0; cell < states.length; cell++) {
			const column = cell % columns;
			const row = Math.floor(cell / columns);
			if (arrival.kind === 'builds') {
				states[cell] = hasRippleReached(arrival.order(column, row), arrived) ? picture.states[cell] : before[cell];
				continue;
			}
			const crest = arrived * (farthestCorner + WAVE_CREST_IN_CELLS);
			const fromOrigin = Math.hypot(column - arrival.origin.column, row - arrival.origin.row);
			if (fromOrigin > crest) states[cell] = before[cell];
			else if (fromOrigin <= crest - WAVE_CREST_IN_CELLS) states[cell] = picture.states[cell];
			else states[cell] = before[cell] === DOT_ABSENT && picture.states[cell] === DOT_ABSENT ? DOT_ABSENT : DOT_FILLED;
		}
		return states;
	};

	const holding = (index: number, heldSeconds: number) => {
		const { picture, animate } = beats[index];
		if (!animate) return picture.states;
		states.set(picture.states);
		animate(states, heldSeconds);
		return states;
	};

	const penFor = (context: CanvasRenderingContext2D, presence: number): StoryPen => ({
		text: (text, own = 1) => paintDotStoryText(context, fontFamily, text, presence * own),
		type(text, heldSeconds, { startsAt: from, charactersPerSecond, cursorLingers = 0.4 }) {
			const typed = text.text.slice(0, Math.max(0, Math.floor((heldSeconds - from) * charactersPerSecond)));
			paintDotStoryText(context, fontFamily, { ...text, text: typed }, presence);
			if (heldSeconds < from || heldSeconds > from + typingSeconds(text, charactersPerSecond) + cursorLingers) return;
			context.font = dotStoryFont(text, fontFamily);
			paintDotStoryCursor(context, text.x + context.measureText(typed).width + CURSOR_GAP, text, presence);
		},
	});

	const clearingFor = (...cleared: StoryBeat[]) => {
		const clears = cleared.flatMap((beat) => beat.clears ?? []);
		if (clears.length === 0) return undefined;
		return (context: CanvasRenderingContext2D) => {
			context.fillStyle = paintColor(context, surfaceColor);
			for (const clear of clears) clear(context);
		};
	};

	for (const beat of beats) beat.write?.({ text: (text) => void document.fonts.load(dotStoryFont(text, fontFamily), text.text), type: (text) => void document.fonts.load(dotStoryFont(text, fontFamily), text.text) }, Infinity);

	return createDotStoryPlayer({
		canvas,
		dotColor,
		surfaceColor,
		onFirstFrame,
		grid,
		resting: { states: Uint8Array.from(holding(resting.beat, resting.heldSeconds)), atSeconds: startsAt[resting.beat] + beats[resting.beat].arrival.seconds + resting.heldSeconds },
		frameAt(storySeconds) {
			const seconds = storySeconds % loopSeconds;
			let index = beats.length - 1;
			while (seconds < startsAt[index]) index--;
			const since = seconds - startsAt[index];
			const { arrival, holdSeconds } = beats[index];
			if (since < arrival.seconds) {
				const leaving = previous(index);
				return {
					states: arriving(index, since / arrival.seconds),
					paintBeneath: clearingFor(beats[index], leaving),
					paintAbove: leaving.write ? (context) => leaving.write!(penFor(context, 1 - clamp01(since / TEXT_FADE_SECONDS)), leaving.holdSeconds) : undefined,
				};
			}
			const heldSeconds = Math.min(since - arrival.seconds, holdSeconds);
			const { write } = beats[index];
			return { states: holding(index, heldSeconds), paintBeneath: clearingFor(beats[index]), paintAbove: write ? (context) => write(penFor(context, clamp01(heldSeconds / TEXT_FADE_SECONDS)), heldSeconds) : undefined };
		},
	});
}

import type { GlyphCell } from '@/components/ds/ui/dot-glyph-cells';
import { DOT_ABSENT, DOT_FILLED, DOT_HOLLOW, type DotGrid } from '@/components/ds/ui/dot-morph-dots';

/** A box of cells within a story's grid. */
export interface Region {
	left: number;
	top: number;
	columns: number;
	rows: number;
}

type CellPosition = Pick<GlyphCell, 'column' | 'row'>;

// Roughly one dot in six flips to the other state, the speckle the brand's dot shader gives its imagery.
const SPECKLE_RATE = 0.16;

function isSpeckled(column: number, row: number) {
	const hash = Math.sin(column * 12.9898 + row * 78.233) * 43758.5453;
	return hash - Math.floor(hash) < SPECKLE_RATE;
}

/** Mostly rings or mostly solid dots, with the shader speckle flipping a few. */
export const isFilledAmongRings = isSpeckled;
export const isFilledAmongSolids = (column: number, row: number) => !isSpeckled(column, row);

export const placeCells = (cells: GlyphCell[], { left, top }: Pick<Region, 'left' | 'top'>): GlyphCell[] => cells.map((cell) => ({ ...cell, column: cell.column + left, row: cell.row + top }));

/** A region's border, one solid dot wide. */
export function outlineCells({ left, top, columns, rows }: Region): GlyphCell[] {
	const cells: GlyphCell[] = [];
	for (let row = top; row < top + rows; row++) {
		for (let column = left; column < left + columns; column++) {
			if (row === top || row === top + rows - 1 || column === left || column === left + columns - 1) cells.push({ column, row, filled: true });
		}
	}
	return cells;
}

export function fillCells({ left, top, columns, rows }: Region, filled: boolean): GlyphCell[] {
	return Array.from({ length: columns * rows }, (_, index) => ({ column: left + (index % columns), row: top + Math.floor(index / columns), filled }));
}

export const cellState = (cell: GlyphCell) => (cell.filled ? DOT_FILLED : DOT_HOLLOW);

export const cellIndexIn =
	({ columns }: DotGrid) =>
	({ column, row }: CellPosition) =>
		row * columns + column;

/** Later cells win where two land on the same dot. */
export function cellStates(grid: DotGrid, cells: GlyphCell[]) {
	const states = new Uint8Array(grid.columns * grid.rows);
	for (const cell of cells) states[cell.row * grid.columns + cell.column] = cellState(cell);
	return states;
}

export function cellsOfStates({ columns }: DotGrid, states: Uint8Array): GlyphCell[] {
	const cells: GlyphCell[] = [];
	states.forEach((state, index) => {
		if (state !== DOT_ABSENT) cells.push({ column: index % columns, row: Math.floor(index / columns), filled: state === DOT_FILLED });
	});
	return cells;
}

// The last dot of a reveal appears this far into it, leaving the rest for it to settle.
const RIPPLE_SHARE = 0.7;

/** Whether a reveal that is `progress` of the way through has reached a dot `share` of the way along it. */
export const hasRippleReached = (share: number, progress: number) => share * RIPPLE_SHARE <= progress;

export const clamp01 = (value: number) => Math.min(1, Math.max(0, value));
export const easeOut = (t: number) => 1 - (1 - t) ** 3;

type DotState = typeof DOT_ABSENT | typeof DOT_HOLLOW | typeof DOT_FILLED;

/** Says what one dot of a picture is; pictures are built by layering painters and then painting the grid with them. */
export type DotPainter = (column: number, row: number) => DotState;

export interface GridPoint {
	column: number;
	row: number;
}

export const LINE_WIDTH = 0.6;
// A dot exactly a line's width from a slanted edge lands on either side of it by rounding; this keeps mirrored shapes mirrored.
const ROUNDING_SLACK = 1e-6;

export function distanceToSegment(column: number, row: number, from: GridPoint, to: GridPoint) {
	const dx = to.column - from.column;
	const dy = to.row - from.row;
	const t = Math.max(0, Math.min(1, ((column - from.column) * dx + (row - from.row) * dy) / (dx * dx + dy * dy)));
	return Math.hypot(column - (from.column + t * dx), row - (from.row + t * dy));
}

export const ringsWithSpeckle: DotPainter = (column, row) => (isFilledAmongRings(column, row) ? DOT_FILLED : DOT_HOLLOW);
export const solidWithSpeckle: DotPainter = (column, row) => (isFilledAmongSolids(column, row) ? DOT_FILLED : DOT_HOLLOW);

/** A shape with a solid outline one dot wide, filled by `interior`. */
export function polygon(corners: GridPoint[], interior: DotPainter): DotPainter {
	const edges = corners.map((from, index) => ({ from, to: corners[(index + 1) % corners.length] }));
	return (column, row) => {
		if (edges.some(({ from, to }) => distanceToSegment(column, row, from, to) < LINE_WIDTH + ROUNDING_SLACK)) return DOT_FILLED;
		const crossings = edges.filter(({ from, to }) => from.row > row !== to.row > row && column < from.column + ((row - from.row) / (to.row - from.row)) * (to.column - from.column));
		return crossings.length % 2 === 1 ? interior(column, row) : DOT_ABSENT;
	};
}

export function rectangle({ left, right, top, bottom }: { left: number; right: number; top: number; bottom: number }, interior: DotPainter): DotPainter {
	return polygon(
		[
			{ column: left, row: top },
			{ column: right, row: top },
			{ column: right, row: bottom },
			{ column: left, row: bottom },
		],
		interior
	);
}

/** Front to back: the first layer that draws a dot wins. */
export function stack(...layers: DotPainter[]): DotPainter {
	return (column, row) => {
		for (const layer of layers) {
			const state = layer(column, row);
			if (state !== DOT_ABSENT) return state;
		}
		return DOT_ABSENT;
	};
}

export function paintedStates({ columns, rows }: DotGrid, painter: DotPainter) {
	const states = new Uint8Array(columns * rows);
	for (let cell = 0; cell < states.length; cell++) states[cell] = painter(cell % columns, Math.floor(cell / columns));
	return states;
}

/** A round shape with a solid outline one dot wide, filled by `interior`. */
export function disc(centre: GridPoint, radius: number, interior: DotPainter): DotPainter {
	return (column, row) => {
		const fromCentre = Math.hypot(column - centre.column, row - centre.row);
		if (fromCentre > radius + ROUNDING_SLACK) return DOT_ABSENT;
		return fromCentre > radius - 1 ? DOT_FILLED : interior(column, row);
	};
}

export const solid: DotPainter = () => DOT_FILLED;
export const rings: DotPainter = () => DOT_HOLLOW;
export const clear: DotPainter = () => DOT_ABSENT;

/** Paints `painter` only where `isInside` holds, so one shape can be cut to another. */
export const within =
	(isInside: (column: number, row: number) => boolean, painter: DotPainter): DotPainter =>
	(column, row) =>
		isInside(column, row) ? painter(column, row) : DOT_ABSENT;

export const isInRegion = ({ left, top, columns, rows }: Region, column: number, row: number) => column >= left && column < left + columns && row >= top && row < top + rows;

export type DotShape = (column: number, row: number) => boolean;

/** Paints `shape` into `states` with a solid outline one dot wide, filled by `interior`; dots outside it are left as they are. */
export function paintShape({ columns, rows }: DotGrid, states: Uint8Array, shape: DotShape, interior: DotPainter) {
	for (let row = 0; row < rows; row++) {
		for (let column = 0; column < columns; column++) {
			if (!shape(column, row)) continue;
			const isEdge = !shape(column - 1, row) || !shape(column + 1, row) || !shape(column, row - 1) || !shape(column, row + 1);
			states[row * columns + column] = isEdge ? DOT_FILLED : interior(column, row);
		}
	}
	return states;
}

export interface DotBox {
	left: number;
	right: number;
	top: number;
	bottom: number;
}

export const isInDotBox = ({ left, right, top, bottom }: DotBox, column: number, row: number) => column >= left && column <= right && row >= top && row <= bottom;

// A corner dot this far past the radius still belongs to the corner, which keeps small radii from looking clipped.
const CORNER_SLACK = 0.3;

/** A box with its corners rounded to `radius`. */
export const roundedBox =
	(box: DotBox, radius: number): DotShape =>
	(column, row) => {
		const across = Math.max(box.left + radius - column, 0, column - (box.right - radius));
		const down = Math.max(box.top + radius - row, 0, row - (box.bottom - radius));
		return isInDotBox(box, column, row) && Math.hypot(across, down) <= radius + CORNER_SLACK;
	};

import { paintColor } from '@/components/ds/ui/ds-color';
import { createDotField, type DotGrid } from '@/components/ds/ui/dot-morph-dots';

/**
 * Plays a picture in the brand dot grid as one endless loop. The story says what the grid looks like at any second;
 * the player eases the dots there, so a changing edge swells and drains its dots rather than switching them.
 */

export interface DotStoryFrame {
	states: Uint8Array;
	/** Painted in grid units under the dots. */
	paintBeneath?: (context: CanvasRenderingContext2D) => void;
	/** Painted in grid units over the dots. */
	paintAbove?: (context: CanvasRenderingContext2D) => void;
}

export interface DotStoryText {
	text: string;
	x: number;
	/** The text's baseline. */
	y: number;
	size: number;
	weight: number;
	/** Set in a lighter grey, for labels that should read as secondary. */
	muted?: boolean;
	/** Overrides the grey, as when a label is cut out of solid dots in the card's colour. */
	color?: string;
	anchor?: 'start' | 'middle' | 'end';
}

export interface DotStoryPlayer {
	setRunning: (isRunning: boolean) => void;
	resize: () => void;
	destroy: () => void;
}

/** What the page hands a story to draw with. */
export interface DotStoryStage {
	canvas: HTMLCanvasElement;
	dotColor: string;
	/** The card's own colour, repainted around the dots so a backdrop pattern never shows through the picture. */
	surfaceColor: string;
	/** The data font's family as the page resolved it, so text is set in the same Doto the rest of the brand uses. */
	fontFamily: string;
	onFirstFrame: () => void;
}

interface DotStoryPlayerOptions extends Pick<DotStoryStage, 'canvas' | 'dotColor' | 'surfaceColor' | 'onFirstFrame'> {
	grid: DotGrid;
	/** The picture the static art shows, and the second of the story it belongs to, so the canvas takes over unseen. */
	resting: { states: Uint8Array; atSeconds: number };
	frameAt: (storySeconds: number) => DotStoryFrame;
}

// A background tab hands back one huge frame gap; stepping the story across it would skip whole pictures.
const LONGEST_FRAME_SECONDS = 0.05;
const MAX_PIXEL_RATIO = 2;
// Every dot eases over 40ms, so 30 frames a second looks the same as 60 or 120 while a card full of stories repaints
// a half or a quarter as often.
const FRAME_INTERVAL_MS = 1000 / 30;
// rAF timestamps jitter by a millisecond or so; without the slack a 60Hz display would skip two frames in three.
const FRAME_SLACK_MS = 2;

// Text is set in greys rather than the dot blue: at the small sizes the pictures use, blue type washes out against the dots.
export const DOT_STORY_TEXT_COLOR = 'var(--ds-color-neutral-90)';
export const DOT_STORY_MUTED_TEXT_COLOR = 'var(--ds-color-neutral-70)';

export const dotStoryFont = ({ size, weight }: Pick<DotStoryText, 'size' | 'weight'>, fontFamily: string) => `${weight} ${size}px ${fontFamily}`;

export function paintDotStoryText(context: CanvasRenderingContext2D, fontFamily: string, { text, x, y, size, weight, muted = false, color, anchor = 'start' }: DotStoryText, presence = 1) {
	if (presence <= 0 || text.length === 0) return;
	context.font = dotStoryFont({ size, weight }, fontFamily);
	context.textBaseline = 'alphabetic';
	context.textAlign = anchor === 'middle' ? 'center' : anchor;
	const dotColor = context.fillStyle;
	context.fillStyle = paintColor(context, color ?? (muted ? DOT_STORY_MUTED_TEXT_COLOR : DOT_STORY_TEXT_COLOR));
	context.globalAlpha = presence;
	context.fillText(text, x, y);
	context.globalAlpha = 1;
	context.fillStyle = dotColor;
}

/** A block cursor standing at `x` on a line of text, in the text's colour. */
export function paintDotStoryCursor(context: CanvasRenderingContext2D, x: number, { y, size }: Pick<DotStoryText, 'y' | 'size'>, presence = 1) {
	const dotColor = context.fillStyle;
	context.fillStyle = paintColor(context, DOT_STORY_TEXT_COLOR);
	context.globalAlpha = presence;
	context.fillRect(x, y - size * 0.78, size * 0.5, size * 0.84);
	context.globalAlpha = 1;
	context.fillStyle = dotColor;
}

export function createDotStoryPlayer({ canvas, dotColor, surfaceColor, onFirstFrame, grid, resting, frameAt }: DotStoryPlayerOptions): DotStoryPlayer {
	const context = canvas.getContext('2d');
	if (!context) throw new Error('2D canvas is unavailable');
	const bleed = grid.haloRadius;
	const surfaceWidth = grid.columns * grid.pitch + bleed * 2;
	const dots = createDotField(grid);
	const palette = { dots: dotColor, background: surfaceColor };

	let isRunning = false;
	let hasDrawn = false;
	let frameRequest = 0;
	let lastFrameAt = 0;
	let storySeconds = resting.atSeconds;

	const draw = ({ paintBeneath, paintAbove }: DotStoryFrame) => {
		context.setTransform(1, 0, 0, 1, 0, 0);
		context.clearRect(0, 0, canvas.width, canvas.height);
		const scale = canvas.width / surfaceWidth;
		context.setTransform(scale, 0, 0, scale, bleed * scale, bleed * scale);
		paintBeneath?.(context);
		dots.draw(context, palette);
		context.fillStyle = dotColor;
		paintAbove?.(context);
	};

	const resize = () => {
		const pixelRatio = Math.min(window.devicePixelRatio || 1, MAX_PIXEL_RATIO);
		const width = Math.round(canvas.clientWidth * pixelRatio);
		const height = Math.round(canvas.clientHeight * pixelRatio);
		if (canvas.width === width && canvas.height === height) return;
		canvas.width = width;
		canvas.height = height;
		if (hasDrawn) draw(frameAt(storySeconds));
	};

	const step = (now: number) => {
		if (now - lastFrameAt < FRAME_INTERVAL_MS - FRAME_SLACK_MS) {
			frameRequest = requestAnimationFrame(step);
			return;
		}
		const seconds = Math.min((now - lastFrameAt) / 1000, LONGEST_FRAME_SECONDS);
		lastFrameAt = now;
		storySeconds += seconds;
		const frame = frameAt(storySeconds);
		dots.advance(frame.states, seconds);
		draw(frame);
		frameRequest = requestAnimationFrame(step);
	};

	return {
		setRunning(next) {
			if (next === isRunning) return;
			isRunning = next;
			if (!next) {
				cancelAnimationFrame(frameRequest);
				return;
			}
			if (!hasDrawn) {
				resize();
				dots.seed(resting.states);
				draw(frameAt(storySeconds));
				hasDrawn = true;
				onFirstFrame();
			}
			lastFrameAt = performance.now();
			frameRequest = requestAnimationFrame(step);
		},
		resize,
		destroy() {
			cancelAnimationFrame(frameRequest);
			isRunning = false;
		},
	};
}

/**
 * Many same-sized dots as one SVG path, each a closed pair of arcs. A picture of a thousand dots is then a handful of
 * DOM nodes rather than a thousand `<circle>`s for the browser to style, lay out and React to hydrate.
 */
export function dotsPath(centres: Iterable<{ cx: number; cy: number }>, radius: number) {
	const diameter = +(radius * 2).toFixed(2);
	const r = +radius.toFixed(2);
	let path = '';
	for (const { cx, cy } of centres) path += `M${+(cx - radius).toFixed(2)} ${+cy.toFixed(2)}a${r} ${r} 0 1 0 ${diameter} 0a${r} ${r} 0 1 0 ${-diameter} 0`;
	return path;
}

const cache = new WeakMap<Element, Map<string, string>>();

// Canvas paint cannot read CSS custom properties, so token colors given as var(--ds-...) are resolved against the element.
export function resolveColor(element: Element, value: string): string {
	const match = value.match(/^var\((--[a-z0-9-]+)\)$/);
	if (!match) return value;
	let byName = cache.get(element);
	if (!byName) cache.set(element, (byName = new Map()));
	const hit = byName.get(match[1]);
	if (hit) return hit;
	const resolved = getComputedStyle(element).getPropertyValue(match[1]).trim();
	byName.set(match[1], resolved);
	return resolved;
}

export const paintColor = (context: CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D, value: string) =>
	'canvas' in context && context.canvas instanceof HTMLCanvasElement && context.canvas.isConnected ? resolveColor(context.canvas, value) : resolveColor(document.documentElement, value);

// Lives outside the pattern's client module: a server component importing a constant from a 'use client' file receives a client reference, not the string.
export const HERO_PATTERN_HOLE_ATTRIBUTE = 'data-hero-pattern-hole';

/**
 * `text` clears each rendered line, `box` the element's box, `snug-box` the box with just enough margin that no dot
 * touches it, and `tight-box` the box with only a sliver of margin (items packed close together). `cover` keeps the dots but places no solid cluster there: for opaque content that hides the
 * dots itself and moves, like a carousel's cards, so the pattern never has to re-draw around them.
 */
export type HeroPatternHole = 'text' | 'box' | 'snug-box' | 'tight-box' | 'cover';

import { paintColor } from '@/components/ds/ui/ds-color';
const SAMPLES_PER_CELL = 4;
const MIN_COVERAGE = 0.35;
// Below this spread the logo is effectively one colour, so every covered cell is drawn solid.
const MIN_LUMINANCE_SPREAD = 0.25;
const TILE_CORNER_INSET = 0.12;
const TILE_CORNER_TOLERANCE = 60;
const TILE_CELL_TOLERANCE = 90;
// A logo that fills its whole box is drawn as an app-icon tile, so its dot corners are rounded like one.
const SOLID_BOX_FILL = 0.9;
const TILE_CORNER_RADIUS = 0.22;

export interface LogoCell {
	column: number;
	row: number;
	filled: boolean;
}

type Rgb = [number, number, number];

interface CellSample {
	column: number;
	row: number;
	coverage: number;
	color: Rgb;
}

interface LogoSample {
	cells: CellSample[];
	tileColor: Rgb | null;
}

const colorDistance = (a: Rgb, b: Rgb) => Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1]) + Math.abs(a[2] - b[2]);
const luminance = ([red, green, blue]: Rgb) => (0.2126 * red + 0.7152 * green + 0.0722 * blue) / 255;

// App-icon logos are a solid tile with the mark inside. Reading the tile colour just inside its corners lets the
// tile become the ring frame and the mark the solid dots, instead of one solid square.
function detectTileColor(pixels: Uint8ClampedArray, size: number, left: number, top: number, width: number, height: number): Rgb | null {
	const inset = Math.max(1, Math.round(Math.min(width, height) * TILE_CORNER_INSET));
	const corners = [
		[left + inset, top + inset],
		[left + width - 1 - inset, top + inset],
		[left + inset, top + height - 1 - inset],
		[left + width - 1 - inset, top + height - 1 - inset],
	].map(([x, y]) => {
		const offset = (Math.round(y) * size + Math.round(x)) * 4;
		return { alpha: pixels[offset + 3], color: [pixels[offset], pixels[offset + 1], pixels[offset + 2]] as Rgb };
	});
	if (corners.some((corner) => corner.alpha < 230)) return null;
	const average = [0, 1, 2].map((channel) => corners.reduce((sum, corner) => sum + corner.color[channel], 0) / corners.length) as Rgb;
	return corners.every((corner) => colorDistance(corner.color, average) < TILE_CORNER_TOLERANCE) ? average : null;
}

// Remote logos (media.brand.dev) send no CORS headers, which would taint the canvas; the Next image
// optimiser serves them from our own origin. Local files load directly, since the optimiser skips SVGs.
function sameOriginSource(src: string) {
	return /^https?:\/\//.test(src) ? `/_next/image?url=${encodeURIComponent(src)}&w=256&q=75` : src;
}

function loadImage(src: string) {
	return new Promise<HTMLImageElement>((resolve, reject) => {
		const image = new window.Image();
		image.crossOrigin = 'anonymous';
		image.onload = () => resolve(image);
		image.onerror = reject;
		image.src = sameOriginSource(src);
	});
}

function sampleLogo(image: HTMLImageElement, background: string | undefined, cellsPerSide: number): LogoSample {
	const size = cellsPerSide * SAMPLES_PER_CELL;
	const canvas = document.createElement('canvas');
	canvas.width = size;
	canvas.height = size;
	const context = canvas.getContext('2d', { willReadFrequently: true });
	if (!context) return { cells: [], tileColor: null };

	const scale = Math.min(size / image.naturalWidth, size / image.naturalHeight);
	const width = image.naturalWidth * scale;
	const height = image.naturalHeight * scale;
	const left = (size - width) / 2;
	const top = (size - height) / 2;
	if (background) {
		context.fillStyle = paintColor(context, background);
		context.fillRect(left, top, width, height);
	}
	context.drawImage(image, left, top, width, height);
	const pixels = context.getImageData(0, 0, size, size).data;

	const cells: CellSample[] = [];
	for (let row = 0; row < cellsPerSide; row++) {
		for (let column = 0; column < cellsPerSide; column++) {
			let alpha = 0;
			const weighted: Rgb = [0, 0, 0];
			for (let y = 0; y < SAMPLES_PER_CELL; y++) {
				for (let x = 0; x < SAMPLES_PER_CELL; x++) {
					const offset = ((row * SAMPLES_PER_CELL + y) * size + column * SAMPLES_PER_CELL + x) * 4;
					const pixelAlpha = pixels[offset + 3] / 255;
					alpha += pixelAlpha;
					for (const channel of [0, 1, 2]) weighted[channel] += pixelAlpha * pixels[offset + channel];
				}
			}
			const color = weighted.map((channel) => (alpha > 0 ? channel / alpha : 0)) as Rgb;
			cells.push({ column, row, coverage: alpha / SAMPLES_PER_CELL ** 2, color });
		}
	}
	return { cells, tileColor: detectTileColor(pixels, size, left, top, width, height) };
}

function isInsideRoundedBox(cell: CellSample, box: { left: number; top: number; right: number; bottom: number }, radius: number) {
	const nearestX = Math.min(Math.max(cell.column, box.left + radius), box.right - radius);
	const nearestY = Math.min(Math.max(cell.row, box.top + radius), box.bottom - radius);
	return Math.hypot(cell.column - nearestX, cell.row - nearestY) <= radius;
}

function roundSolidBoxCorners(covered: CellSample[]) {
	if (covered.length === 0) return covered;
	const columns = covered.map((cell) => cell.column);
	const rows = covered.map((cell) => cell.row);
	const box = { left: Math.min(...columns), top: Math.min(...rows), right: Math.max(...columns), bottom: Math.max(...rows) };
	const boxArea = (box.right - box.left + 1) * (box.bottom - box.top + 1);
	if (covered.length / boxArea < SOLID_BOX_FILL) return covered;
	const radius = Math.min(box.right - box.left, box.bottom - box.top) * TILE_CORNER_RADIUS;
	return covered.filter((cell) => isInsideRoundedBox(cell, box, radius));
}

// Without a tile, the lighter parts become solid dots and the darker parts rings, so the mark keeps its contrast on a blue card.
function classifyCells({ cells, tileColor }: LogoSample): LogoCell[] {
	const covered = roundSolidBoxCorners(cells.filter((cell) => cell.coverage >= MIN_COVERAGE));
	const toCell = (cell: CellSample, filled: boolean) => ({ column: cell.column, row: cell.row, filled });
	if (tileColor) return covered.map((cell) => toCell(cell, colorDistance(cell.color, tileColor) >= TILE_CELL_TOLERANCE));

	const luminances = covered.map((cell) => luminance(cell.color));
	const darkest = Math.min(...luminances);
	const lightest = Math.max(...luminances);
	if (lightest - darkest < MIN_LUMINANCE_SPREAD) return covered.map((cell) => toCell(cell, true));
	const threshold = (darkest + lightest) / 2;
	return covered.map((cell) => toCell(cell, luminance(cell.color) >= threshold));
}

/** Samples a logo onto a square grid of cells, leaving out the cells the logo doesn't cover. */
export async function sampleLogoCells(src: string, { background, cellsPerSide }: { background?: string; cellsPerSide: number }): Promise<LogoCell[]> {
	const image = await loadImage(src);
	return classifyCells(sampleLogo(image, background, cellsPerSide));
}

'use client';

import { useEffect, useRef } from 'react';

/**
 * Dropped inside an SVG, it pauses that SVG's SMIL animations while the SVG is off screen. SMIL keeps ticking (and
 * restyling and repainting) whether or not anyone can see it.
 */
export function PauseWhenOffscreen() {
	const markerRef = useRef<SVGGElement>(null);

	useEffect(() => {
		const svg = markerRef.current?.ownerSVGElement;
		if (!svg) return;
		const observer = new IntersectionObserver(([entry]) => {
			if (entry.isIntersecting) svg.unpauseAnimations();
			else svg.pauseAnimations();
		});
		observer.observe(svg);
		return () => observer.disconnect();
	}, []);

	return <g ref={markerRef} />;
}

import type { DotMorphPlayer } from '@/components/ds/ui/dot-morph-player';
import { useEffect, useState, type RefObject } from 'react';

/** Resolves to null when the art isn't ready to morph yet, so the next hover tries again. */
export type LoadDotMorph = (canvas: HTMLCanvasElement, onPlayingChange: (isPlaying: boolean) => void) => Promise<DotMorphPlayer | null>;

/** While in view the morph loops: it plays, then rests long enough to ease fully back to the art before the next go. */
const VIEW_PLAY_MS = 2600;
const VIEW_REST_MS = 1400;

/**
 * Plays a dot morph on the canvas while the card around it is hovered or holds keyboard focus, and, with
 * `playOnView`, on a loop while the card is in view, so it also plays where there is no hover. The card is the
 * nearest link, or the nearest element marked `data-hover-morph` when the card isn't itself a link.
 * Returns whether the canvas is currently standing in for the static art.
 */
export function useHoverDotMorph(canvasRef: RefObject<HTMLCanvasElement | null>, load: LoadDotMorph, { playOnView = false }: { playOnView?: boolean } = {}) {
	const [isPlaying, setIsPlaying] = useState(false);

	useEffect(() => {
		const canvas = canvasRef.current;
		const card = canvas?.closest<HTMLElement>('[data-hover-morph], a');
		if (!canvas || !card) return;
		if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

		let player: DotMorphPlayer | null = null;
		let isLoading = false;
		let isDisposed = false;
		let isPointerOver = false;
		let isFocused = false;
		let isPlayingForView = false;
		let viewPlayTimer = 0;

		// The morph's code only downloads once a card is first hovered; if that fails, the static art simply stays.
		const start = async () => {
			isLoading = true;
			try {
				const loaded = await load(canvas, setIsPlaying);
				if (isDisposed) {
					loaded?.destroy();
					return;
				}
				player = loaded;
				player?.setHovering(isPointerOver || isFocused || isPlayingForView);
			} catch {
				player = null;
			} finally {
				isLoading = false;
			}
		};

		const update = () => {
			const isActive = isPointerOver || isFocused || isPlayingForView;
			if (player) player.setHovering(isActive);
			else if (isActive && !isLoading) void start();
		};
		const handlePointerEnter = (event: PointerEvent) => {
			// A touch reports a hover it never really has; the tap is already on its way to the link.
			if (event.pointerType === 'touch') return;
			isPointerOver = true;
			update();
		};
		const handlePointerLeave = () => {
			isPointerOver = false;
			update();
		};
		const handleFocusIn = (event: FocusEvent) => {
			isFocused = event.target instanceof Element && event.target.matches(':focus-visible');
			update();
		};
		const handleFocusOut = () => {
			isFocused = false;
			update();
		};

		card.addEventListener('pointerenter', handlePointerEnter);
		card.addEventListener('pointerleave', handlePointerLeave);
		card.addEventListener('focusin', handleFocusIn);
		card.addEventListener('focusout', handleFocusOut);
		const resizeObserver = new ResizeObserver(() => player?.resize());
		resizeObserver.observe(canvas);
		const viewObserver = playOnView
			? new IntersectionObserver(
					([entry]) => {
						window.clearTimeout(viewPlayTimer);
						const loop = (play: boolean) => {
							isPlayingForView = play;
							update();
							viewPlayTimer = window.setTimeout(() => loop(!play), play ? VIEW_PLAY_MS : VIEW_REST_MS);
						};
						if (entry.isIntersecting) {
							loop(true);
						} else {
							isPlayingForView = false;
							update();
						}
					},
					{ threshold: 0.6 }
				)
			: null;
		viewObserver?.observe(card);

		return () => {
			isDisposed = true;
			card.removeEventListener('pointerenter', handlePointerEnter);
			card.removeEventListener('pointerleave', handlePointerLeave);
			card.removeEventListener('focusin', handleFocusIn);
			card.removeEventListener('focusout', handleFocusOut);
			resizeObserver.disconnect();
			viewObserver?.disconnect();
			window.clearTimeout(viewPlayTimer);
			player?.destroy();
			setIsPlaying(false);
		};
	}, [canvasRef, load, playOnView]);

	return isPlaying;
}
